            future_def = future_deficit(post_cann, post_pir, rounds_left=2)

            # new flag: does this action kill a position‑2 pirate this round?
            instant_kill2 = 1 if kills_position2(new_cann, pirates) else 0

            # tie‑breaker: prefer spawn over move, then lower column numbers for determinism
            tie = (0 if act[0] == "spawn" else 1, act)

            # incorporate the new flag (higher is better, so use -instant_kill2)
            key = (deficit_now,
